function authErrorMessage(error){const message=String(error?.message||error||'').toLowerCase();if(message.includes('invalid login credentials'))return 'El correo o la contraseña no son correctos.';if(message.includes('email not confirmed'))return 'Confirma tu correo antes de iniciar sesión.';if(message.includes('user already registered'))return 'Ya existe una cuenta con este correo. Intenta iniciar sesión.';if(message.includes('password should be at least'))return 'La contraseña debe tener al menos 6 caracteres.';if(message.includes('rate limit'))return 'Hiciste demasiados intentos. Espera un momento y vuelve a probar.';return 'No pudimos completar esta acción. Revisa tus datos e inténtalo nuevamente.'}
let toastTimer;function toast(message,tone='info'){const raw=String(message||''),looksTechnical=/invalid|credentials|email not confirmed|already registered|password should|rate limit|auth/i.test(raw),localized=looksTechnical?authErrorMessage(raw):raw;const el=document.querySelector('#toast');(document.querySelector('dialog[open]')||document.body).append(el);el.dataset.tone=tone;el.setAttribute('role',tone==='error'?'alert':'status');el.innerHTML=`<span aria-hidden="true">${tone==='error'?'!':'✓'}</span><p>${safe(localized)}</p>`;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500)}
